// ① 활성 규칙 조회 준비 — global 캐시에서 규칙 로드 + 센서 축적
var sensorData = msg.sensorData;

// 센서 데이터 축적
var allSensorData = context.get('allSensorData') || {};
if (sensorData && sensorData.houseId) {
    allSensorData[sensorData.houseId] = sensorData;
    context.set('allSensorData', allSensorData);
}

// 이번 분에서 이미 평가했으면 스킵
var lastSent = context.get('lastSentMin') || -1;
var nowMin = new Date().getMinutes();
if (lastSent === nowMin) {
    return null;
}
context.set('lastSentMin', nowMin);

// global 캐시에서 규칙 로드 (SQLite 노드 불필요)
var rules = global.get('automationRules') || [];

var houseCount = Object.keys(allSensorData).length;
node.warn('🔔 규칙 평가 시작: ' + houseCount + '개 하우스, ' + rules.length + '개 규칙');
node.status({ fill: 'green', shape: 'dot', text: houseCount + '개 하우스, ' + rules.length + '개 규칙' });

// ② 에 직접 전달 (SQLite 노드 경유 없음)
var newMsg = {
    payload: rules,
    allSensorData: allSensorData
};

// 다음 사이클을 위해 센서 데이터 리셋
