const FARM_ID = global.get('farmId') || env.get('FARM_ID') || 'farm_0001';

// --- 규칙 로드 ---
var rules = msg.automationRules || global.get('automationRules') || [];
if (typeof rules === 'string') {
    try { rules = JSON.parse(rules); } catch(e) { rules = []; }
