// ================================================================
// ⑤-B 스케줄 실행 핸들러 (실제 Modbus 상태 기반 판단)
// ================================================================

var rule = flow.get('pendingRule');
var actions = flow.get('pendingActions');

if (!rule || !actions || actions.length === 0) {
    node.warn('⚠️ 스케줄 실행: pending 데이터 없음');
    return null;
}

var coils = msg.payload;
if (!Array.isArray(coils)) {
    node.warn('⚠️ Modbus 읽기 실패 — 상태 확인 없이 실행');
    coils = null;
}

var ruleId = rule._id || rule.id;
var REVERSE_CMD = { on: 'off', off: 'on' };
var pcServer = global.get('pcServerUrl') || 'https://api.smartgreen.kr';

function findModbus(deviceId) {
    var cached = global.get('modbus_cfg_' + deviceId);
    if (cached) return cached;
    var houseConfig = global.get('houseConfig') || {};
    var houses = houseConfig.houses || [];
    for (var i = 0; i < houses.length; i++) {
        var devices = houses[i].devices || [];
        for (var j = 0; j < devices.length; j++) {
            if (devices[j].deviceId === deviceId && devices[j].modbus) {
                global.set('modbus_cfg_' + deviceId, devices[j].modbus);
                return devices[j].modbus;
            }
        }
    }
    return null;
}

function getActualState(modbus) {
    if (!coils || !modbus || modbus.address == null) return null;
    var openCoil = !!coils[modbus.address];
    var closeCoil = (modbus.address2 != null) ? !!coils[modbus.address2] : false;
    if (modbus.controlType === 'bidir') {
        if (openCoil && !closeCoil) return 'open';
        if (!openCoil && closeCoil) return 'closed';
        if (!openCoil && !closeCoil) return 'idle';
        return 'unknown';
    } else {
        return openCoil ? 'on' : 'off';
    }
}

function updateDeviceState(deviceId, command) {
    var ds = global.get('deviceStates') || {};
    if (command === 'open') ds[deviceId] = 'open';
    else if (command === 'close') ds[deviceId] = 'closed';
    else if (command === 'stop') ds[deviceId] = 'idle';
    else if (command === 'on') ds[deviceId] = 'on';
    else if (command === 'off') ds[deviceId] = 'off';
    global.set('deviceStates', ds);
}

function sendControlLog(action, command) {
    var logMsg = {
        method: 'POST',
        url: pcServer + '/internal/control-log',
        headers: { 'Content-Type': 'application/json', 'x-api-key': global.get('sensorApiKey') || 'smartfarm-sensor-key' },
        payload: {
            farmId: rule.farmId || global.get('farmId') || 'farm_0001',
            houseId: rule.houseId || 'house_0001',
            deviceId: action.deviceId,
            deviceType: action.deviceType || 'relay',
            deviceName: action.deviceName || action.deviceId,
            command: command,
            ruleName: rule.name,
            ruleId: ruleId,
            reason: rule.name + ' (자동화 스케줄)'
        }
    };
    node.send([null, null, null, logMsg, null]);
}

function sendSqliteLog(deviceId, command, source) {
    var lm = RED.util.cloneMessage(msg);
    lm.topic = "INSERT INTO control_logs (timestamp, device_id, command, source, synced) VALUES ('" + new Date().toISOString() + "', '" + deviceId + "', '" + command + "', '" + source + "', 0)";
    lm.payload = [];
    node.send([null, null, null, null, lm]);
}

var controlMsgs = [];
var logParts = [];

actions.forEach(function(action) {
    var modbus = findModbus(action.deviceId);
    if (!modbus) {
        node.warn('⚠️ ' + action.deviceId + ': Modbus 설정 없음');
        return;
    }

    var actualState = getActualState(modbus);
    if (actualState) {
        node.warn('🔍 ' + action.deviceId + ' 실제 릴레이 상태: ' + actualState + ' (Modbus 코일)');
        var isAlready = (action.command === 'open' && actualState === 'open') ||
                        (action.command === 'close' && actualState === 'closed') ||
                        (action.command === 'on' && actualState === 'on') ||
                        (action.command === 'off' && actualState === 'off');
        if (isAlready) {
            node.warn('⏭️ ' + action.deviceId + ': 실제 릴레이 ' + actualState + ' → 스킵');
            return;
        }
    } else {
        node.warn('🔍 ' + action.deviceId + ' Modbus 상태 확인 불가 — 그대로 실행');
    }

    var controlMsg = RED.util.cloneMessage(msg);
    controlMsg.payload = {
        deviceId: action.deviceId,
        command: action.command,
        modbus: modbus,
        source: 'automation_scheduler'
    };
    controlMsgs.push(controlMsg);
    updateDeviceState(action.deviceId, action.command);
    logParts.push(action.deviceId + ' ' + action.command);
    sendControlLog(action, action.command);
    sendSqliteLog(action.deviceId, action.command, 'automation_scheduler');

    var duration = action.duration || 0;
    if (action.durationUnit === 'minutes') duration = duration * 60;
    else if (action.durationUnit === 'hours') duration = duration * 3600;

    if (duration > 0) {
        var reverseCmd = (modbus.controlType === 'bidir') ? 'stop' : REVERSE_CMD[action.command];
        if (!reverseCmd) return;
        node.warn('⏱️ Duration: ' + action.deviceId + ' ' + duration + '초 후 → ' + reverseCmd);

        (function(act, rev, dur, mb) {
            setTimeout(function() {
                var reverseMsg = RED.util.cloneMessage(msg);
                reverseMsg.payload = {
                    deviceId: act.deviceId,
                    command: rev,
                    modbus: mb,
                    source: 'automation_duration'
                };
                node.warn('⏳ Duration 종료: ' + act.deviceId + ' → ' + rev);
                node.send([reverseMsg, null, null, null, null]);
                updateDeviceState(act.deviceId, rev);
                sendControlLog(act, rev);
                sendSqliteLog(act.deviceId, rev, 'automation_duration');
            }, dur * 1000);
        })(action, reverseCmd, duration, modbus);
    }
});

flow.set('pendingRule', null);
flow.set('pendingActions', null);

var now = new Date().toISOString();
var dbMsg = {
    topic: "UPDATE automation_rules SET last_triggered_at = '" + now +
           "', trigger_count = " + ((rule.triggerCount || 0) + 1) +
           " WHERE id = '" + ruleId + "'",
    payload: []
};

node.warn('🎯 스케줄 실행 완료: ' + rule.name + ' → ' + (logParts.join(', ') || '(전부 스킵)'));

if (controlMsgs.length > 0) {
    var firstMsg = controlMsgs[0];
    for (var k = 1; k < controlMsgs.length; k++) {
        (function(m, delay) {
            setTimeout(function() { node.send([m, null, null, null, null]); }, delay);
        })(controlMsgs[k], k * 500);
    }
    return [firstMsg, dbMsg, { payload: '스케줄 실행: ' + rule.name }, null, null];
}

return [null, dbMsg, { payload: '스케줄 실행(제어없음): ' + rule.name }, null, null];

// ================================================================
// ⑤-A 스케줄 실행 준비 (Modbus 상태 읽기 요청)
// ================================================================

var rule = msg.scheduledRule;
var actions = msg.scheduledActions;

if (!rule || !actions || actions.length === 0) {
    node.warn('⚠️ 스케줄 실행: 규칙 또는 액션 없음');
    return null;
}

// 액션 정보를 flow context에 저장 (⑤-B에서 사용)
flow.set('pendingRule', rule);
flow.set('pendingActions', actions);

// Modbus 읽기 대상 unitId 수집
var houseConfig = global.get('houseConfig') || {};
var houses = houseConfig.houses || [];
var unitIds = {};

actions.forEach(function(action) {
    for (var i = 0; i < houses.length; i++) {
        var devices = houses[i].devices || [];
        for (var j = 0; j < devices.length; j++) {
            if (devices[j].deviceId === action.deviceId && devices[j].modbus) {
                var uid = devices[j].modbus.unitId || 1;
                unitIds[uid] = true;
            }
        }
    }
});

var firstUnitId = parseInt(Object.keys(unitIds)[0]) || 1;

msg.payload = {
    value: msg.payload,
    unitid: firstUnitId,
    fc: 1,
    address: 0,
    quantity: 8
};
msg.topic = 'schedule_precheck';

node.warn('🔍 스케줄 사전 확인: unitId=' + firstUnitId + ' Modbus 읽기');
return msg;

var farmId = env.get('FARM_ID') || global.get('FARM_ID') || global.get('farmId') || 'farm_0001';
msg.url = 'https://api.smartgreen.kr/api/automation/' + farmId;
msg.headers = { 'x-api-key': 'smartfarm-sensor-key' };
return msg;

info:
프론트엔드에서 제어 버튼 클릭 → API Gateway → Lambda → IoT Core MQTT publish → 이 노드에서 수신

토픽 패턴: smartfarm/{house_id}/{device_id}/control
페이로드: { command, timestamp, house_id, window_id, operator, request_id }

func:
// MQTT 토픽에서 장치 ID 추출
// 토픽: smartfarm/house1/window1/control
const topicParts = msg.topic.split('/');
const houseId = topicParts[1] || 'unknown';
const deviceId = topicParts[2] || 'unknown';

// 페이로드 파싱
const payload = msg.payload;
const command = payload.command || 'unknown';
const operator = payload.operator || 'unknown';
const requestId = payload.request_id || '';
const timestamp = payload.timestamp || new Date().toISOString();

// 장치 유형 판별
let deviceType = 'unknown';
if (deviceId.startsWith('window')) deviceType = 'window';
else if (deviceId.startsWith('fan')) deviceType = 'fan';
else if (deviceId.startsWith('heater')) deviceType = 'heater';
else if (deviceId.startsWith('valve')) deviceType = 'valve';

// 메시지에 파싱 결과 첨부
msg.control = {
    houseId,
    deviceId,
    deviceType,
    command,
    operator,
    requestId,
    timestamp,
    raw: payload
};

const cmdLabels = {
    open: '열기', close: '닫기', stop: '정지',
    on: 'ON', off: 'OFF'
};
const label = cmdLabels[command] || command;

node.status({
    fill: 'green',
    shape: 'dot',
    text: `${label} ← ${houseId}/${deviceId} (${operator})`
});

node.warn(`📥 제어 수신: ${houseId}/${deviceId} ${command.toUpperCase()} by ${operator} [${requestId}]`);

return msg;

// Modbus 릴레이 제어 (Waveshare FC15 / Eletechsup FC06)
// 출력 1: Modbus Flex Write
// 출력 2: MQTT out (장치 위치 보고)
const ctrl = msg.control || {};
const pl = msg.payload || {};
var modbus = pl.modbus || msg.modbus || ctrl.modbus;
const command = ctrl.command || pl.command || 'stop';
const duration = ctrl.duration || pl.duration || 0;

const deviceId = ctrl.deviceId || pl.deviceId || pl.window_id || pl.device_id || 'unknown';
const reqId = msg._requestId || null;

node.warn('📦 수신 duration=' + duration + ' command=' + command + ' deviceId=' + deviceId);

// === 장치 상태 기록 함수 ===
function saveDeviceState(devId, cmd, cType) {
    var states = global.get('deviceStates') || {};
    if (cType === 'bidir') {
        var positions = global.get('devicePositions') || {};
        var moves = global.get('movements') || {};
        if (cmd === 'open' || cmd === 'close') {
            states[devId] = cmd === 'open' ? 'open' : 'closed';
            moves[devId] = {
                startedAt: Date.now(),
                startPos: positions[devId] !== undefined ? positions[devId] : (cmd === 'open' ? 0 : 100),
                command: cmd
            };
            global.set('movements', moves);
        } else if (cmd === 'stop') {
            var move = moves[devId];
            var modbusCfg = global.get('modbus_cfg_' + devId);
            var newPos = positions[devId] !== undefined ? positions[devId] : 0;
            if (move && move.startedAt && modbusCfg) {
                var elapsed = (Date.now() - move.startedAt) / 1000;
                var fullDur = move.command === 'open' ? modbusCfg.openDuration : modbusCfg.closeDuration;
                if (fullDur > 0) {
                    var ratio = Math.min(1, elapsed / fullDur);
                    if (move.command === 'open') {
                        newPos = Math.min(100, Math.round(move.startPos + (100 - move.startPos) * ratio));
                    } else {
                        newPos = Math.max(0, Math.round(move.startPos - move.startPos * ratio));
                    }
                    if (move.command === 'close' && newPos <= 5) newPos = 0;
                    if (move.command === 'open' && newPos >= 95) newPos = 100;
                    positions[devId] = newPos;
                    global.set('devicePositions', positions);
                    node.warn('📍 Duration 위치 계산: ' + devId + ' ' + move.startPos + '% → ' + newPos + '% (' + elapsed.toFixed(1) + 's / ' + fullDur + 's)');
                }
            }
            if (newPos === 100) states[devId] = 'open';
            else if (newPos === 0) states[devId] = 'closed';
            else states[devId] = 'idle';
            delete moves[devId];
            global.set('movements', moves);
            var fid = global.get('FARM_ID') || env.get('FARM_ID') || 'farm_0001';
            node.send([null, {
                topic: 'smartfarm/' + fid + '/device/position',
                payload: JSON.stringify({ deviceId: devId, position: newPos, command: 'stop' })
            }]);
        }
    } else {
        if (cmd === 'on' || cmd === 'open') states[devId] = 'on';
        else states[devId] = 'off';
    }
    global.set('deviceStates', states);
}

// === MQTT 위치 보고 함수 ===
function reportPosition(devId, pos) {
    var farmId = global.get('FARM_ID') || env.get('FARM_ID') || 'farm_0001';
    var mqttMsg = {
        topic: 'smartfarm/' + farmId + '/device/position',
        payload: JSON.stringify({ deviceId: devId, position: pos, command: 'stop' })
    };
    node.send([null, mqttMsg]);
    node.warn('📍 MQTT 위치 보고: ' + farmId + '/' + devId + ' → ' + pos + '%');
}

// === duration 자동 정지 함수 ===
function scheduleAutoStop(devId, uId, addr, addr2, modType, dur, cmd) {
    if (dur <= 0) return;
    var timerKey = 'autoStop_' + devId;
    var existing = global.get(timerKey);
    if (existing) clearTimeout(existing);

    var timer = setTimeout(function() {
        var stopMsg = RED.util.cloneMessage(msg);
        if (modType === 'eletechsup') {
            stopMsg.payload = { fc: 6, unitid: uId, address: addr, quantity: 1, value: 0x0200 };
            node.send([stopMsg, null]);
            setTimeout(function() {
                var stopMsg2 = RED.util.cloneMessage(msg);
                stopMsg2.payload = { fc: 6, unitid: uId, address: addr2, quantity: 1, value: 0x0200 };
                node.send([stopMsg2, null]);
            }, 300);
        } else {
            stopMsg.payload = { fc: 15, unitid: uId, address: addr, quantity: 2, value: [false, false] };
            node.send([stopMsg, null]);
        }
        global.set(timerKey, null);
        saveDeviceState(devId, 'stop', 'bidir');
        // 위치 저장 + MQTT 보고
        var positions = global.get('devicePositions') || {};
        positions[devId] = (cmd === 'open') ? 100 : 0;
        global.set('devicePositions', positions);
        reportPosition(devId, positions[devId]);
        node.warn('⏱️ 자동 정지: ' + devId + ' (' + dur + '초) → 위치: ' + positions[devId] + '%');
        node.status({ fill: 'grey', shape: 'ring', text: '자동 정지: ' + devId + ' ' + positions[devId] + '%' });
    }, dur * 1000);

    global.set(timerKey, timer);
    node.warn('⏱️ 자동 정지 예약: ' + devId + ' → ' + dur + '초 후');
}

// === Modbus 설정 캐시 ===
if (modbus) {
    global.set('modbus_cfg_' + deviceId, modbus);
} else {
    modbus = global.get('modbus_cfg_' + deviceId);
    if (modbus) {
        node.warn('[Modbus] ' + deviceId + ': 캐시에서 modbus 설정 로드');
    }
}

flow.set('lastControl', { deviceId: deviceId, command: command, houseId: ctrl.houseId || pl.houseId || '' });

if (!modbus || modbus.address === null || modbus.address === undefined) {
    node.warn('[Modbus] ' + deviceId + ': modbus 설정 없음 — 무시');
    node.status({ fill: 'yellow', shape: 'ring', text: deviceId + ': modbus 미설정' });
    return null;
}

const unitId = modbus.unitId || 1;
const controlType = modbus.controlType || 'single';
const address = modbus.address;
const address2 = modbus.address2;
const moduleType = modbus.moduleType || 'waveshare';

node.warn('[Modbus] ' + moduleType + ' uid:' + unitId + ' ' + deviceId + ' ' + command + ' (' + controlType + ') duration=' + duration);

// stop 명령 시 기존 자동 정지 타이머 취소
if (command === 'stop') {
    var timerKey = 'autoStop_' + deviceId;
    var existing = global.get(timerKey);
    if (existing) {
        clearTimeout(existing);
        global.set(timerKey, null);
        node.warn('⏱️ 자동 정지 취소: ' + deviceId + ' (수동 정지)');
    }
}

if (moduleType === 'eletechsup') {
    if (controlType === 'bidir') {
        if (command === 'open') {
            var msg2 = RED.util.cloneMessage(msg);
            msg.payload = { fc: 6, unitid: unitId, address: address2, quantity: 1, value: 0x0200 };
            msg2.payload = { fc: 6, unitid: unitId, address: address, quantity: 1, value: 0x0100 };
            global.set('_pendingModbus', { requestId: reqId, isLastWrite: false });
            setTimeout(function () {
                global.set('_pendingModbus', { requestId: reqId, isLastWrite: true });
                node.send([msg2, null]);
            }, 300);
            node.status({ fill: 'green', shape: 'dot', text: 'FC06 열기: uid' + unitId + ' reg' + address });
            saveDeviceState(deviceId, command, controlType);
            scheduleAutoStop(deviceId, unitId, address, address2, moduleType, duration, command);
            return [msg, null];
        } else if (command === 'close') {
            var msg2 = RED.util.cloneMessage(msg);
            msg.payload = { fc: 6, unitid: unitId, address: address, quantity: 1, value: 0x0200 };
            msg2.payload = { fc: 6, unitid: unitId, address: address2, quantity: 1, value: 0x0100 };
            global.set('_pendingModbus', { requestId: reqId, isLastWrite: false });
            setTimeout(function () {
                global.set('_pendingModbus', { requestId: reqId, isLastWrite: true });
                node.send([msg2, null]);
            }, 300);
            node.status({ fill: 'green', shape: 'dot', text: 'FC06 닫기: uid' + unitId + ' reg' + address2 });
            saveDeviceState(deviceId, command, controlType);
            scheduleAutoStop(deviceId, unitId, address, address2, moduleType, duration, command);
            return [msg, null];
        } else {
            var msg2 = RED.util.cloneMessage(msg);
            msg.payload = { fc: 6, unitid: unitId, address: address, quantity: 1, value: 0x0200 };
            msg2.payload = { fc: 6, unitid: unitId, address: address2, quantity: 1, value: 0x0200 };
            global.set('_pendingModbus', { requestId: reqId, isLastWrite: false });
            setTimeout(function () {
                global.set('_pendingModbus', { requestId: reqId, isLastWrite: true });
                node.send([msg2, null]);
            }, 300);
            node.status({ fill: 'grey', shape: 'dot', text: 'FC06 정지: uid' + unitId + ' ALL OFF' });
            saveDeviceState(deviceId, command, controlType);
            return [msg, null];
        }
    } else {
        var value = (command === 'on' || command === 'open') ? 0x0100 : 0x0200;
        msg.payload = { fc: 6, unitid: unitId, address: address, quantity: 1, value: value };
        global.set('_pendingModbus', { requestId: reqId, isLastWrite: true });
        node.status({ fill: 'green', shape: 'dot', text: 'FC06 uid' + unitId + ' reg' + address });
        saveDeviceState(deviceId, command, controlType);
        return [msg, null];
    }
} else {
    if (controlType === 'bidir') {
        if (command === 'open') {
            msg.payload = { fc: 15, unitid: unitId, address: address, quantity: 2, value: [true, false] };
            node.status({ fill: 'green', shape: 'dot', text: 'FC15 열기: uid' + unitId + ' ch' + address });
        } else if (command === 'close') {
            msg.payload = { fc: 15, unitid: unitId, address: address, quantity: 2, value: [false, true] };
            node.status({ fill: 'green', shape: 'dot', text: 'FC15 닫기: uid' + unitId + ' ch' + address2 });
        } else {
            msg.payload = { fc: 15, unitid: unitId, address: address, quantity: 2, value: [false, false] };
            node.status({ fill: 'grey', shape: 'dot', text: 'FC15 정지: ALL OFF' });
        }
    } else {
        var on = (command === 'on' || command === 'open');
        msg.payload = { fc: 15, unitid: unitId, address: address, quantity: 1, value: [on] };
        node.status({ fill: 'green', shape: 'dot', text: 'FC15 uid' + unitId + ' ch' + address + '=' + (on ? 'ON' : 'OFF') });
    }
    global.set('_pendingModbus', { requestId: reqId, isLastWrite: true });
    saveDeviceState(deviceId, command, controlType);
    if (controlType === 'bidir' && (command === 'open' || command === 'close')) {
        scheduleAutoStop(deviceId, unitId, address, address2, moduleType, duration, command);
    }
    return [msg, null];
}

// 제어 응답을 IoT Core로 전송
// 프론트엔드에서 이 토픽을 구독하면 실시간 상태 확인 가능

const { houseId, deviceId, command, requestId, operator } = msg.control;

msg.topic = `smartfarm/${houseId}/${deviceId}/response`;
msg.payload = {
    request_id: requestId,
    house_id: houseId,
    device_id: deviceId,
    command: command,
    status: 'received',
    operator: operator,
    executed_at: new Date().toISOString(),
    device_client: 'MyFarmPi_01'
};

node.status({
    fill: 'blue',
    shape: 'dot',
    text: `응답 → ${msg.topic}`
});

return msg;

// Modbus Write 성공 응답이면 무시 (출력2에도 성공 메시지가 옴)
if (msg.queueUnitId !== undefined) {
    node.status({ fill: 'green', shape: 'dot', text: '성공 — 무시' });
    return null;
}
var lastCtrl = flow.get('lastControl') || {};
var deviceId = lastCtrl.deviceId || 'unknown';
var command = lastCtrl.command || 'unknown';
var houseId = lastCtrl.houseId || '';

var errorMsg = msg.payload?.error || msg.error?.message || 'Modbus Write 실패';

node.warn('⚡ 제어 실패: ' + deviceId + ' (' + command + ') - ' + errorMsg);

msg = {
    payload: {
        alarm_type: 'CONTROL_FAILURE',
        severity: 'WARNING',
        sensorId: deviceId,
        houseId: houseId,
        message: deviceId + ' 제어 실패 (' + command + ') - ' + errorMsg,
        cooldownMinutes: 10,
        metadata: {
            deviceId: deviceId,
            command: command,
            error: errorMsg,
            houseId: houseId
        }
    },
    headers: { 'content-type': 'application/json' }
};

node.status({ fill: 'red', shape: 'dot', text: deviceId + ' 실패' });
return msg;

var pending = global.get('_pendingModbus');
node.warn('완료응답: pending=' + JSON.stringify(pending));

if (!pending || !pending.isLastWrite) return null;
if (!pending.requestId) return null;

global.set('controlDone_' + pending.requestId, { done: true, timestamp: Date.now() });
global.set('_pendingModbus', null);
node.warn('Modbus 완료 저장됨: ' + pending.requestId);

setTimeout(function() {
    global.set('controlDone_' + pending.requestId, null);
}, 30000);

return null;

// retained 메시지 무시 (재연결 시 이전 명령 재실행 방지)
if (msg.retain) {
    node.warn('⏭️ retained MQTT 메시지 무시');
    return null;
}

// ★ 자동화 메시지 호환: msg.control → msg.payload 변환
if (msg.control && (!msg.payload || !msg.payload.command)) {
    msg.payload = {
        device_id: msg.control.deviceId,
        house_id: msg.control.houseId,
        command: msg.control.command,
        operator: msg.control.operator,
    };
    msg._requestId = msg.control.requestId || null;
}

// ★ modbus 설정 캐시: 수동 제어 시 저장, 자동화 시 조회
var cacheDevId = msg.payload.device_id || msg.payload.window_id || 'unknown';
if (msg.payload.modbus) {
    global.set('modbus_cfg_' + cacheDevId, msg.payload.modbus);
} else {
    var cachedModbus = global.get('modbus_cfg_' + cacheDevId);
    if (cachedModbus) {
        msg.payload.modbus = cachedModbus;
    }
}

// MQTT 페이로드에서 modbus 설정 추출
const modbus = msg.payload.modbus || msg.modbus;
const command = msg.payload.command || msg.command || 'stop';
const deviceId = msg.payload.window_id || msg.payload.device_id || 'unknown';
const houseId = msg.payload.house_id || 'unknown';

// ★ 로컬 제어의 requestId 전달 (Modbus 완료 후 HTTP 응답용)
const reqId = msg._requestId || null;

if (!modbus || modbus.address === null || modbus.address === undefined) {
    node.warn(`[Modbus] ${deviceId}: modbus 설정 없음 — 무시`);
    node.status({ fill: 'yellow', shape: 'ring', text: `${deviceId}: modbus 미설정` });
    return null;
}

const unitId = modbus.unitId || 1;
const controlType = modbus.controlType || 'single';
const address = modbus.address;
const address2 = modbus.address2;
const moduleType = modbus.moduleType || 'waveshare';

node.warn(`[Modbus] ${moduleType} uid:${unitId} ${deviceId} ${command} (${controlType})`);

// ━━━ moduleType별 분기 ━━━

if (moduleType === 'eletechsup') {
    // ━━━ Eletechsup: FC06 (Write Single Register) ━━━

    if (controlType === 'bidir') {
        if (command === 'open') {
            var msg2 = RED.util.cloneMessage(msg);
            msg.payload = { fc: 6, unitid: unitId, address: address2, quantity: 1, value: 0x0200 };
            msg._isLastWrite = false;
            msg._requestId = reqId;
            msg2.payload = { fc: 6, unitid: unitId, address: address, quantity: 1, value: 0x0100 };
            msg2._isLastWrite = true;
            msg2._requestId = reqId;
            global.set('_pendingModbus', { requestId: msg._requestId, isLastWrite: false });
            setTimeout(function () {
                global.set('_pendingModbus', { requestId: msg2._requestId, isLastWrite: true });
                node.send(msg2);
            }, 300);
            node.status({ fill: 'green', shape: 'dot', text: `FC06 열기: uid${unitId} reg${address} ON` });
            return msg;
        } else if (command === 'close') {
            var msg2 = RED.util.cloneMessage(msg);
            msg.payload = { fc: 6, unitid: unitId, address: address, quantity: 1, value: 0x0200 };
            msg._isLastWrite = false;
            msg._requestId = reqId;
            msg2.payload = { fc: 6, unitid: unitId, address: address2, quantity: 1, value: 0x0100 };
            msg2._isLastWrite = true;
            msg2._requestId = reqId;
            global.set('_pendingModbus', { requestId: msg._requestId, isLastWrite: false });
            setTimeout(function () {
                global.set('_pendingModbus', { requestId: msg2._requestId, isLastWrite: true });
                node.send(msg2);
            }, 300);
            node.status({ fill: 'green', shape: 'dot', text: `FC06 닫기: uid${unitId} reg${address2} ON` });
            return msg;
        } else {
            var msg2 = RED.util.cloneMessage(msg);
            msg.payload = { fc: 6, unitid: unitId, address: address, quantity: 1, value: 0x0200 };
            msg._isLastWrite = false;
            msg._requestId = reqId;
            msg2.payload = { fc: 6, unitid: unitId, address: address2, quantity: 1, value: 0x0200 };
            msg2._isLastWrite = true;
            msg2._requestId = reqId;
            global.set('_pendingModbus', { requestId: msg._requestId, isLastWrite: false });
            setTimeout(function () {
                global.set('_pendingModbus', { requestId: msg2._requestId, isLastWrite: true });
                node.send(msg2);
            }, 300);
            node.status({ fill: 'grey', shape: 'dot', text: `FC06 정지: uid${unitId} ALL OFF` });
            return msg;
        }
    } else {
        const value = (command === 'on' || command === 'open') ? 0x0100 : 0x0200;
        msg.payload = { fc: 6, unitid: unitId, address: address, quantity: 1, value: value };
        msg._isLastWrite = true;
        msg._requestId = reqId;
        global.set('_pendingModbus', { requestId: reqId, isLastWrite: true });
        node.status({ fill: 'green', shape: 'dot', text: `FC06 uid${unitId} reg${address} val:0x${value.toString(16)}` });
        return msg;
    }

} else {
    // ━━━ Waveshare (기본): FC15 (Write Multiple Coils) ━━━

    if (controlType === 'bidir') {
        if (command === 'open') {
            msg.payload = { fc: 15, unitid: unitId, address: address, quantity: 2, value: [true, false] };
            node.status({ fill: 'green', shape: 'dot', text: `FC15 열기: uid${unitId} ch${address}=ON ch${address2}=OFF` });
        } else if (command === 'close') {
            msg.payload = { fc: 15, unitid: unitId, address: address, quantity: 2, value: [false, true] };
            node.status({ fill: 'green', shape: 'dot', text: `FC15 닫기: uid${unitId} ch${address}=OFF ch${address2}=ON` });
        } else {
            msg.payload = { fc: 15, unitid: unitId, address: address, quantity: 2, value: [false, false] };
            node.status({ fill: 'grey', shape: 'dot', text: `FC15 정지: uid${unitId} ALL OFF` });
        }
    } else {
        const on = (command === 'on' || command === 'open');
        msg.payload = { fc: 15, unitid: unitId, address: address, quantity: 1, value: [on] };
        node.status({ fill: 'green', shape: 'dot', text: `FC15 uid${unitId} ch${address}=${on ? 'ON' : 'OFF'}` });
    }

    msg._isLastWrite = true;
    msg._requestId = reqId;
    global.set('_pendingModbus', { requestId: reqId, isLastWrite: true });
    return msg;
}

// Heartbeat 메시지 생성
// cpu_temp, disk_usage는 실배포 시 os 모듈로 교체

var farmId = env.get('FARM_ID') || global.get('FARM_ID') || 'default-farm';

// Node-RED 시작 시간 기록 (최초 실행 시)
var startTime = global.get('node_start_time');
if (!startTime) {
    startTime = Date.now();
    global.set('node_start_time', startTime);
}
var uptimeSec = Math.floor((Date.now() - startTime) / 1000);

var heartbeat = {
    farmId: farmId,
    timestamp: new Date().toISOString(),
    uptime: uptimeSec,
    cpu_temp: 0,
    disk_usage: 0,
    operating_state: flow.get('operating_state') || 'STOPPED',
    memory_usage: 0
};

msg.payload = JSON.stringify(heartbeat);
msg.topic = 'farm/' + farmId + '/heartbeat';

node.status({ fill: 'green', shape: 'dot', text: 'uptime: ' + uptimeSec + 's' });

return msg;

// 수동 수집은 즉시 통과
if (msg.topic === 'manual') return msg;

const now = Date.now();
const nextCollectAt = global.get('nextCollectAt') || 0;

if (now < nextCollectAt) {
    const remain = Math.round((nextCollectAt - now) / 1000);
    node.status({ fill: 'blue', shape: 'ring', text: '대기 (' + remain + '초 후)' });
    return null; // 스킵
}

// houseConfig에서 최소 intervalSeconds 읽기
const config = global.get('houseConfig');
const houses = config && config.houses ? config.houses : [];
let interval = 600; // 기본 10분
for (const h of houses) {
    const hi = (h.collection && h.collection.intervalSeconds) || 600;
    if (hi < interval) interval = hi;
}
if (interval < 10) interval = 10; // 최소 10초 보장

global.set('nextCollectAt', now + interval * 1000);
global.set('appliedIntervalSeconds', interval);
node.status({ fill: 'green', shape: 'dot', text: '수집 (' + interval + '초 주기)' });
return msg;

const SERVER_URL = env.get('SERVER_URL') || 'https://api.smartgreen.kr';
const FARM_ID = env.get('FARM_ID') || 'farm_0001';
const HOUSE_ID = env.get('HOUSE_ID') || 'house_0001';
const API_KEY = env.get('SENSOR_API_KEY') || 'smartfarm-sensor-key';

// operationMode가 아직 설정 안 된 경우 (재시작 직후)
// serverOnline도 체크하여 기본값 결정
const serverOnline = global.get('serverOnline');
const operationMode = global.get('operationMode') || (serverOnline === true ? 'online' : 'offline');

if (operationMode === 'online') {
    // 온라인: 서버에서 설정 가져오기
    msg.url = `${SERVER_URL}/api/config/farm/${FARM_ID}`;
    msg.method = 'GET';
    msg.headers = { 'Content-Type': 'application/json', 'x-api-key': API_KEY };
    node.status({ fill: 'blue', shape: 'dot', text: '온라인: 서버 config 요청' });
    return [msg, null, null]; // 출력1: HTTP Request
} else {
    // 오프라인: global 캐시 → SQLite 캐시
    const cachedConfig = global.get('houseConfig');
    if (cachedConfig) {
        msg.config = cachedConfig;
        node.status({ fill: 'yellow', shape: 'dot', text: '오프라인: global 캐시 사용' });
        return [null, msg, null]; // 출력2: 센서 수집으로
    } else {
        // SQLite config_cache에서 로드
        msg.topic = 'SELECT config_json FROM config_cache ORDER BY version DESC LIMIT 1';
        node.status({ fill: 'yellow', shape: 'ring', text: '오프라인: SQLite 캐시 조회' });
        return [null, null, msg]; // 출력3: SQLite 조회
    }
}

// 서버 응답 실패 → 캐시 폴백
if (msg.statusCode !== 200) {
    var cached = global.get('houseConfig');
    if (cached) {
        node.warn('⚠️ 서버 응답 실패 (status=' + msg.statusCode + '), 캐시 사용');
        msg.config = cached;
        return [msg, null, null];
    }
    node.error('❌ 서버 응답 실패, 캐시도 없음');
    return [null, null, null];
}

var response = msg.payload;
if (!response || !response.success) {
    node.error('설정 오류: ' + (response ? response.error || 'success=false' : 'payload null'));
    return [null, null, null];
}

var rawData = response.data;
var config;

// GET /api/config/farm/:farmId → data가 배열(하우스 목록)
if (Array.isArray(rawData)) {
    var FARM_ID = env.get('FARM_ID') || 'farm_0001';
    var enabledHouses = rawData.filter(function(h) { return h.enabled !== false; });
    var maxVersion = 0;
    rawData.forEach(function(h) {
        var v = h.configVersion || 0;
        if (v > maxVersion) maxVersion = v;
    });
    config = { farmId: FARM_ID, houses: enabledHouses, configVersion: maxVersion };
} else if (rawData && rawData.houses) {
    config = rawData;
} else {
    node.warn('⚠️ 예상 외 data 형식: ' + JSON.stringify(rawData).substring(0, 200));
    config = rawData;
}

if (!config || !config.houses) {
    node.error('❌ config 파싱 실패');
    var fb = global.get('houseConfig');
    if (fb) { msg.config = fb; return [msg, null, null]; }
    return [null, null, null];
}

// 항상 global 갱신 (최신 하우스 목록 반영)
global.set('houseConfig', config);
msg.config = config;

// configVersion 변경 감지 → ACK + SQLite 캐시 + 즉시 재수집
var cachedVersion = flow.get('lastConfigVersion') || 0;
if (config.configVersion > cachedVersion) {
    flow.set('lastConfigVersion', config.configVersion);
    node.warn('📋 설정 업데이트: v' + cachedVersion + ' → v' + config.configVersion + ' (' + config.houses.length + '개 하우스)');
    global.set('nextCollectAt', 0); // 즉시 재수집

    var cacheMsg = {
        topic: 'INSERT OR REPLACE INTO config_cache (id, farm_id, house_id, config_json, version, updated_at) VALUES (1, $1, $2, $3, $4, $5)',
        payload: [
            config.farmId || 'farm_0001',
            config.houses[0] ? config.houses[0].houseId : 'house_0001',
            JSON.stringify(config),
            config.configVersion || 1,
            new Date().toISOString()
        ]
    };

    var SERVER_URL = env.get('SERVER_URL') || 'https://api.smartgreen.kr';
    var API_KEY = env.get('SENSOR_API_KEY') || 'smartfarm-sensor-key';
    var ackMsg = {
        url: SERVER_URL + '/api/config/' + config.farmId + '/rpi-ack',
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'x-api-key': API_KEY },
        payload: {
            configVersion: config.configVersion,
            appliedAt: new Date().toISOString(),
            houses: config.houses.map(function(h) {
                return {
                    houseId: h.houseId,
                    intervalSeconds: (h.collection && h.collection.intervalSeconds) || 60
                };
            })
        }
    };
    node.warn('📤 RPi ACK 전송: v' + config.configVersion);
    return [msg, cacheMsg, ackMsg];
}

return [msg, null, null];

const rows = msg.payload || [];

if (rows.length > 0 && rows[0].config_json) {
    try {
        const config = JSON.parse(rows[0].config_json);
        global.set('houseConfig', config);
        msg.config = config;
        node.warn('📋 SQLite에서 config 복원 완료');
        node.status({ fill: 'green', shape: 'dot', text: 'SQLite config 복원' });
        return msg;
    } catch (e) {
        node.error('❌ config JSON 파싱 실패: ' + e.message);
    }
}

node.error('❌ SQLite config_cache도 비어있음 - 서버에 1회 접속 필요');
node.status({ fill: 'red', shape: 'dot', text: 'config 없음!' });
return null;

const config = msg.config || global.get('houseConfig');
const modbusRaw = msg.payload;

if (!config) {
    node.error('❌ config 없음, 수집 중단');
    return null;
}

// Modbus 실측 데이터 파싱
let realData = {};
if (Array.isArray(modbusRaw) && modbusRaw.length >= 2) {
    realData.humidity = modbusRaw[0] / 10;
    let temp = modbusRaw[1] / 10;
    if (modbusRaw[1] > 0x7FFF) {
        temp = -(0xFFFF - modbusRaw[1] + 1) / 10;
    }
    realData.temperature = temp;
    node.warn('🌡️ Modbus 실측: ' + realData.temperature + '°C, ' + realData.humidity + '%RH');
} else {
    node.warn('⚠️ Modbus 데이터 없음, 시뮬레이션 사용');
}

// msg.modbusReadings가 있으면 사용 (sensor-modbus-read-flow 경유)
var modbusReadings = msg.modbusReadings || realData || {};

let housesToCollect = [];

if (config.houses && config.houses.length > 0) {
    housesToCollect = config.houses.filter(h => h.enabled !== false);
} else if (config.sensors) {
    housesToCollect = [{ houseId: config.houseId, sensors: config.sensors }];
}

if (housesToCollect.length === 0) {
    node.error('❌ 활성 하우스 없음');
    return null;
}

const farmId = config.farmId;
const messages = [];

for (const house of housesToCollect) {
    const sensors = house.sensors || [];
    const houseId = house.houseId;
    const enabledSensors = sensors.filter(s => s.enabled);

    if (enabledSensors.length === 0) {
        continue;
    }

    const sensorData = {};
    for (const sensor of enabledSensors) {
        try {
            let value;

            // modbusReadings에 값이 있으면 우선 사용
            if (modbusReadings[sensor.sensorId] !== undefined) {
                value = modbusReadings[sensor.sensorId];
            } else {
                switch (sensor.sensorId) {
                    case 'temp_0001':
                        value = (realData.temperature !== undefined)
                            ? realData.temperature
                            : parseFloat((Math.random() * 10 + 20).toFixed(1));
                        break;
                    case 'humidity_0001':
                        value = (realData.humidity !== undefined)
                            ? realData.humidity
                            : parseFloat((Math.random() * 20 + 50).toFixed(1));
                        break;
                    case 'co2_0001':
                        value = parseInt(Math.random() * 200 + 400);
                        break;
                    default:
                        if (sensor.type === 'number') {
                            const min = sensor.min !== null ? sensor.min : 0;
                            const max = sensor.max !== null ? sensor.max : 100;
                            value = parseFloat((Math.random() * (max - min) + min).toFixed(sensor.precision || 1));
                        } else if (sensor.type === 'boolean') {
                            value = Math.random() > 0.5;
                        } else {
                            value = 'OK';
                        }
                }
            }
            sensorData[sensor.sensorId] = value;
        } catch (e) {
            node.error('센서 읽기 실패: ' + sensor.sensorId + ' - ' + e.message);
            sensorData[sensor.sensorId] = null;
        }
    }

    messages.push({
        payload: {
            farmId: farmId,
            houseId: houseId,
            data: sensorData,
            timestamp: new Date().toISOString(),
            deviceInfo: {
                deviceId: env.get('DEVICE_ID') || 'rpi_0001',
                ip: '192.168.137.30',
                version: '2.0.0-offline'
            }
        }
    });
}

if (messages.length === 0) {
    node.warn('⚠️ 모든 하우스에 활성 센서 없음');
    return null;
}

const totalSensors = messages.reduce((sum, m) => sum + Object.keys(m.payload.data).length, 0);
node.warn('📡 ' + messages.length + '개 하우스, 총 ' + totalSensors + '개 센서 수집');
node.status({ fill: 'green', shape: 'dot', text: messages.length + '개 하우스 ' + totalSensors + '개 센서' });

// ━━━ Modbus 버스 전체 장애 감지 ━━━
var busAlarmMsg = null;
var totalModbusSensors = 0;
var totalModbusFailed = 0;

for (const house of housesToCollect) {
    const sensors = (house.sensors || []).filter(s => s.enabled);
    for (const sensor of sensors) {
        if (sensor.modbus && sensor.modbus.unitId != null) {
            totalModbusSensors++;
            if (modbusReadings[sensor.sensorId] === undefined) {
                totalModbusFailed++;
            }
        }
    }
}

if (totalModbusSensors >= 2 && totalModbusFailed === totalModbusSensors) {
    var busFailCount = (flow.get('busFailCount') || 0) + 1;
    flow.set('busFailCount', busFailCount);
    node.warn('🔌 Modbus 버스 전체 실패 (' + busFailCount + '사이클 연속)');

    if (busFailCount >= 2) {
        var lastBusAlarm = flow.get('lastBusAlarmTime') || 0;
        var now = Date.now();
        if (now - lastBusAlarm > 60 * 60 * 1000) {
            flow.set('lastBusAlarmTime', now);
            busAlarmMsg = {
                payload: {
                    alarm_type: 'MODBUS_BUS_FAILURE',
                    severity: 'CRITICAL',
                    message: 'Modbus RS-485 버스 전체 통신 장애 — ' + totalModbusSensors + '개 센서 모두 응답 없음 (' + busFailCount + '사이클 연속)',
                    cooldownMinutes: 60,
                    metadata: {
                        totalModbusSensors: totalModbusSensors,
                        consecutiveFailCycles: busFailCount
                    }
                },
                headers: { 'content-type': 'application/json' }
            };
            node.warn('🚨 Modbus 버스 장애 알림 전송!');
        }
    }
} else {
    if (flow.get('busFailCount') > 0) {
        node.warn('✅ Modbus 버스 정상 복구');
    }
    flow.set('busFailCount', 0);
}

return [messages, busAlarmMsg];

const { farmId, houseId, data, timestamp } = msg.payload;
const ts = timestamp || new Date().toISOString();

// 센서 데이터 수집
const entries = Object.entries(data).filter(([k, v]) => v !== null && v !== undefined);

if (entries.length === 0) {
    node.warn('⚠️ 저장할 데이터 없음');
    return null;
}

// 위치 파라미터 쿼리로 개별 INSERT (센서별 msg 배열)
// node-red-node-sqlite msg.topic 모드: msg.payload 배열 + $N 파라미터 사용
const messages = entries.map(([sensorId, value]) => ({
    topic: 'INSERT INTO sensor_data (timestamp, farm_id, house_id, sensor_id, value, synced) VALUES ($1, $2, $3, $4, $5, 0)',
    payload: [ts, farmId, houseId, sensorId, value],
    _insertTimestamp: ts,
    _sensorCount: entries.length,
    _isLast: false,
    _originalPayload: msg.payload,
    _houseId: houseId
}));

// 마지막 메시지에 표시 (모드 분기용)
const srvOnline = global.get('serverOnline');
const opMode = global.get('operationMode') || (srvOnline === true ? 'online' : 'offline');
messages[messages.length - 1]._isLast = true;
messages[messages.length - 1]._operationMode = opMode;

node.warn('💾 SQLite INSERT: ' + houseId + ' ' + entries.length + '건');
return [messages];

// 마지막 INSERT 메시지만 처리 (나머지는 통과)
if (!msg._isLast) { return null; }

const serverOnline = global.get('serverOnline');
const mode = msg._operationMode || global.get('operationMode') || (serverOnline === true ? 'online' : 'offline');

// 자동화 평가용 메시지 (모드와 무관하게 항상 실행)
var evalMsg = null;
if (msg._originalPayload) {
    evalMsg = {
        sensorData: {
            farmId: msg._originalPayload.farmId,
            houseId: msg._originalPayload.houseId,
            data: msg._originalPayload.data
        }
    };
}

// === 디버그 로그 추가 ===
if (evalMsg) {
    node.warn('📊 자동화 평가 전달: ' + evalMsg.sensorData.farmId + '/' + evalMsg.sensorData.houseId);
} else {
    node.warn('⚠️ evalMsg null: _originalPayload 없음');
}

// 원본 payload 복원 (서버 전송용)
if (msg._originalPayload) { msg.payload = msg._originalPayload; }

if (mode === 'online') {
    const SERVER_URL = env.get('SERVER_URL') || 'https://api.smartgreen.kr';
    const API_KEY = env.get('SENSOR_API_KEY') || 'smartfarm-sensor-key';

    msg.url = SERVER_URL + '/api/sensors/collect';
    msg.method = 'POST';
    msg.headers = { 'Content-Type': 'application/json', 'x-api-key': API_KEY };
    msg.requestTimeout = 10000;

    node.status({ fill: 'green', shape: 'dot', text: '온라인: SQLite ✓ + 서버 전송' });
    return [msg, null, evalMsg];
} else {
    node.warn('📴 오프라인: SQLite만 저장 (synced=0)');
    node.status({ fill: 'yellow', shape: 'dot', text: '오프라인: SQLite ✓ (' + msg._sensorCount + '건)' });
    msg.payload = '오프라인 저장 완료: ' + msg._sensorCount + '건';
    return [null, msg, evalMsg];
}

if (msg.statusCode === 201 || msg.statusCode === 200) {
    node.warn('✅ 서버 전송 성공 → synced=1');

    const syncMsg = {
        topic: 'UPDATE sensor_data SET synced = 1 WHERE timestamp = $1 AND house_id = $2 AND synced = 0',
        payload: [msg._insertTimestamp, msg._houseId]
    };

    node.status({ fill: 'green', shape: 'dot', text: '서버 전송 ✓ + synced' });
    return [syncMsg, msg];
} else {
    node.warn('⚠️ 서버 전송 실패 (' + msg.statusCode + '): synced=0 유지');
    node.status({ fill: 'yellow', shape: 'ring', text: '전송 실패 (synced=0)' });
    return [null, msg];
}

var errMsg = msg.error ? msg.error.message : 'unknown';
node.warn('❌ SQLite 쓰기 에러: ' + errMsg);
node.status({fill:'red',shape:'dot',text:'SQLite 에러: ' + errMsg.substring(0,30)});

// 에러 카운트 (모니터링용)
var count = global.get('sqliteErrorCount') || 0;
global.set('sqliteErrorCount', count + 1);
global.set('lastSqliteError', {message: errMsg, timestamp: new Date().toISOString()});

return null;

// ================================================================
// Modbus 센서 읽기 준비 — 자동 매핑 추가 버전 (2026-05-01)
// ================================================================
// "센서 수집" 탭 → "Modbus 센서 읽기 준비" 함수 노드 코드 전체 교체
//
// 변경: sensor.modbus 가 비어있을 때 global.sensorModules 의 매칭 모듈로 자동 채움
//   - sensorId prefix 로 register index 추론 (temp_* → 0, humidity_* → 1)
//   - 모듈 등록만 하면 모든 house 의 sensor 가 자동 동작 (UI 매핑 불필요)
// ================================================================

const config = msg.config || global.get('houseConfig');
if (!config) { return [null, msg]; }

// ───────── 자동 매핑: sensor.modbus 비어있으면 global.sensorModules 로 채움 ─────────
const sensorModules = global.get('sensorModules') || [];
const moduleByType = {};
for (const mod of sensorModules) {
    if (mod && mod.sensorType) moduleByType[mod.sensorType] = mod;
}

function inferType(sensorId) {
    const id = String(sensorId || '').toLowerCase();
    // XY-MD02 (humidity 먼저 변종): register 0 = 습도, register 1 = 온도
    if (id.startsWith('temp')) return { type: 'temperature_humidity', registerIndex: 1 };
    if (id.startsWith('humid')) return { type: 'temperature_humidity', registerIndex: 0 };
    if (id.startsWith('co2')) return { type: 'co2', registerIndex: 0 };
    if (id.startsWith('soil_temp')) return { type: 'soil', registerIndex: 0 };
    if (id.startsWith('soil_moist')) return { type: 'soil', registerIndex: 1 };
    if (id.startsWith('ec')) return { type: 'ec', registerIndex: 0 };
    if (id.startsWith('ph')) return { type: 'ph', registerIndex: 0 };
    return null;
}

let autoMapped = 0;
let stalefixed = 0;
for (const house of (config.houses || [])) {
    for (const sensor of (house.sensors || [])) {
        const inferred = inferType(sensor.sensorId);
        if (!inferred) continue;
        const mod = moduleByType[inferred.type];
        if (!mod) continue;
        const m = sensor.modbus;
        // 등록된 모듈과 매핑이 일치하면 그대로 사용
        const matches = m && m.unitId === mod.unitId
            && m.address === (mod.address || 0)
            && m.fc === (mod.fc || 3)
            && m.quantity === (mod.quantity || 1);
        if (matches) continue;
        // 비어있거나 stale 매핑 → 자동매핑으로 덮어쓰기
        const wasStale = m && m.unitId != null;
        sensor.modbus = {
            unitId: mod.unitId,
            fc: mod.fc || 3,
            address: mod.address || 0,
            quantity: mod.quantity || 1,
            registerIndex: inferred.registerIndex,
            divider: mod.divider || 1,
            signed: mod.signed || false,
        };
        if (wasStale) stalefixed++; else autoMapped++;
    }
}

// ───────── 모든 sensor 모음 ─────────
const houses = config.houses || (config.sensors ? [config] : []);
const allSensors = [];

for (const house of houses) {
    if (house.enabled === false) continue;
    const sensors = (house.sensors || []).filter(s => s.enabled !== false && s.modbus && s.modbus.unitId != null && s.modbus.address != null);
    for (const sensor of sensors) {
        allSensors.push({
            houseId: house.houseId || house.id,
            sensorId: sensor.sensorId,
            unitId: sensor.modbus.unitId,
            fc: sensor.modbus.fc || 3,
            address: sensor.modbus.address,
            quantity: sensor.modbus.quantity || 1,
            registerIndex: sensor.modbus.registerIndex || 0,
            divider: sensor.modbus.divider || 1,
            signed: sensor.modbus.signed || false
        });
    }
}

if (allSensors.length === 0) {
    node.status({ fill: 'grey', shape: 'ring', text: 'Modbus 센서 없음' });
    msg.modbusReadings = {};
    return [null, msg];
}

// ───────── unique read 집계 (같은 unitId/fc/address/quantity 는 1번만 read) ─────────
const uniqueReads = [];
const sensorMap = {};
for (const s of allSensors) {
    const key = s.unitId + ':' + s.fc + ':' + s.address + ':' + s.quantity;
    if (!sensorMap[key]) {
        sensorMap[key] = [];
        uniqueReads.push({
            key: key,
            unitId: s.unitId,
            fc: s.fc,
            address: s.address,
            quantity: s.quantity
        });
    }
    sensorMap[key].push(s);
}

flow.set('modbusUniqueReads', uniqueReads);
flow.set('modbusSensorMap', sensorMap);
flow.set('modbusReadIndex', 0);
flow.set('modbusReadings', {});
flow.set('modbusReadConfig', msg.config);

var first = uniqueReads[0];
msg.payload = {
    fc: first.fc,
    unitid: first.unitId,
    address: first.address,
    quantity: first.quantity
};
msg._modbusKey = first.key;

node.status({
    fill: 'blue',
    shape: 'dot',
    text: 'Modbus 1/' + uniqueReads.length
        + (autoMapped ? ' (auto+' + autoMapped + ')' : '')
        + (stalefixed ? ' (stale fix ' + stalefixed + ')' : '')
});
return [msg, null];

const uniqueReads = flow.get('modbusUniqueReads') || [];
var idx = flow.get('modbusReadIndex') || 0;

if (uniqueReads.length === 0 || idx >= uniqueReads.length) {
    return null;
}

var currentRead = uniqueReads[idx];
if (currentRead) {
    var sensorMap = flow.get('modbusSensorMap') || {};
    var sensors = sensorMap[currentRead.key] || [];
    var names = sensors.map(function(s) { return s.sensorId; }).join(',');
    node.warn('Modbus 읽기 실패: ' + names + ' (U' + currentRead.unitId + ':R' + currentRead.address + ')');
}

idx++;
flow.set('modbusReadIndex', idx);

if (idx < uniqueReads.length) {
    var next = uniqueReads[idx];
    msg.payload = {
        fc: next.fc,
        unitid: next.unitId,
        address: next.address,
        quantity: next.quantity
    };
    msg._modbusKey = next.key;
    node.status({ fill: 'yellow', shape: 'ring', text: '에러→다음 ' + (idx + 1) + '/' + uniqueReads.length });
    return [msg, null];
}

flow.set('modbusUniqueReads', []);
msg.modbusReadings = flow.get('modbusReadings') || {};
msg.config = flow.get('modbusReadConfig') || msg.config;
node.status({ fill: 'yellow', shape: 'dot', text: 'Modbus 완료 (일부 에러)' });
return [null, msg];

const uniqueReads = flow.get('modbusUniqueReads') || [];
const sensorMap = flow.get('modbusSensorMap') || {};
var idx = flow.get('modbusReadIndex') || 0;
var readings = flow.get('modbusReadings') || {};

var currentRead = uniqueReads[idx];
if (currentRead && msg.payload) {
    var sensors = sensorMap[currentRead.key] || [];
    for (var i = 0; i < sensors.length; i++) {
        var s = sensors[i];
        var rawValue = Array.isArray(msg.payload) ? msg.payload[s.registerIndex || 0] : msg.payload;
        var parsed = rawValue;
        if (s.signed && rawValue > 0x7FFF) {
            parsed = -(0xFFFF - rawValue + 1);
        }
        if (s.divider && s.divider !== 1) {
            parsed = parsed / s.divider;
        }
        parsed = Math.round(parsed * 100) / 100;
        readings[s.sensorId] = parsed;
    }
    flow.set('modbusReadings', readings);
}

idx++;
flow.set('modbusReadIndex', idx);

if (idx < uniqueReads.length) {
    var next = uniqueReads[idx];
    msg.payload = {
        fc: next.fc,
        unitid: next.unitId,
        address: next.address,
        quantity: next.quantity
    };
    msg._modbusKey = next.key;
    node.status({ fill: 'blue', shape: 'dot', text: 'Modbus 읽기 ' + (idx + 1) + '/' + uniqueReads.length });
    return [msg, null];
}

flow.set('modbusUniqueReads', []);
msg.modbusReadings = readings;
msg.config = flow.get('modbusReadConfig') || msg.config;
var count = Object.keys(readings).length;
node.status({ fill: 'green', shape: 'dot', text: 'Modbus 완료: ' + count + '개 센서' });
return [null, msg];

const ips = msg.payload.trim().split(/\s+/);
const ip = ips[0] || 'unknown';
msg.payload = { ip: ip, allIps: ips };
return msg;

const SERVER_URL = env.get('SERVER_URL') || 'https://api.smartgreen.kr';
msg.url = SERVER_URL + '/health';
msg.method = 'GET';
return msg;

const manualOverride = global.get('manualOverride') || false;
const prevMode = global.get('operationMode') || 'unknown';
const prevServerOnline = global.get('serverOnline');

// 서버 응답 확인
let serverOnline = false;
if (msg.statusCode === 200 && msg.payload && (msg.payload.success === true || msg.payload.status === 'ok')) {
    serverOnline = true;
}

global.set('serverOnline', serverOnline);

// 모드 결정: 수동 스위치 ON → 강제 오프라인
const operationMode = manualOverride ? 'offline' : (serverOnline ? 'online' : 'offline');
global.set('operationMode', operationMode);

let syncMsg = null;
let configMsg = null;

// 상태 변경 감지
if (prevMode !== operationMode) {
    node.warn(`🔄 모드 변경: ${prevMode} → ${operationMode}`);

    // 온라인 전환 시 동기화 트리거 (unknown/offline → online 모두 포함)
    if (prevMode !== 'online' && operationMode === 'online') {
        node.warn('🔄 온라인 복귀! 데이터 동기화 시작...');
        syncMsg = { payload: 'sync_trigger' };
    }
}

// 서버 온라인 + config 미캐시 → config 가져오기 (env var 동적 URL)
if (serverOnline && !global.get('houseConfig')) {
    node.warn('📋 서버에서 config 캐시 가져오기...');
    const SERVER_URL = env.get('SERVER_URL') || 'https://api.smartgreen.kr';
    const FARM_ID = env.get('FARM_ID') || 'farm_0001';
    const API_KEY = env.get('SENSOR_API_KEY') || 'smartfarm-sensor-key';
    configMsg = {
        payload: 'fetch_config',
        url: SERVER_URL + '/api/config/farm/' + FARM_ID,
        method: 'GET',
        headers: { 'x-api-key': API_KEY }
    };
}

// 상태 표시
const modeLabel = operationMode === 'online' ? '온라인' : '오프라인';
const manualLabel = manualOverride ? ' (수동)' : '';
const serverLabel = serverOnline ? '서버 정상' : '서버 다운';
const configLabel = global.get('houseConfig') ? ' | config ✓' : '';

node.status({
    fill: operationMode === 'online' ? 'green' : 'yellow',
    shape: manualOverride ? 'ring' : 'dot',
    text: `${modeLabel}${manualLabel} | ${serverLabel}${configLabel}`
});

msg.payload = {
    operationMode,
    serverOnline,
    manualOverride,
    timestamp: new Date().toISOString()
};

return [msg, syncMsg, configMsg];

// 다른 플로우에서 참조할 수 있도록 상태 요약 저장
global.set('systemStatus', {
    operationMode: msg.payload.operationMode,
    serverOnline: msg.payload.serverOnline,
    manualOverride: msg.payload.manualOverride,
    lastCheck: msg.payload.timestamp
});
return msg;

if (msg.statusCode === 200 && msg.payload && msg.payload.success && msg.payload.data) {
    var rawData = msg.payload.data;
    var config;

    // API가 배열(하우스 목록)을 반환하면 올바른 형식으로 래핑
    if (Array.isArray(rawData)) {
        var FARM_ID = env.get('FARM_ID') || 'farm_0001';
        var enabledHouses = rawData.filter(function(h) { return h.enabled !== false; });
        var maxVersion = 0;
        rawData.forEach(function(h) {
            var v = h.configVersion || 0;
            if (v > maxVersion) maxVersion = v;
        });
        config = { farmId: FARM_ID, houses: enabledHouses, configVersion: maxVersion };
        node.warn('📋 Config 캐시 완료: ' + enabledHouses.length + '개 하우스 (배열→래핑)');
    } else if (rawData.houses) {
        config = rawData;
        node.warn('📋 Config 캐시 완료: ' + (config.houses.length || 0) + '개 하우스');
    } else {
        config = rawData;
        node.warn('📋 Config 캐시 완료: 단일 config');
    }

    global.set('houseConfig', config);
    node.status({ fill: 'green', shape: 'dot', text: (config.houses ? config.houses.length : 0) + '개 하우스 캐시' });

    // SQLite config_cache에도 저장
    msg.topic = 'INSERT OR REPLACE INTO config_cache (id, farm_id, house_id, config_json, version, updated_at) VALUES (1, $1, $2, $3, $4, $5)';
    msg.payload = [
        config.farmId || 'farm_0001',
        config.houses && config.houses[0] ? config.houses[0].houseId : 'house_0001',
        JSON.stringify(config),
        config.configVersion || 1,
        new Date().toISOString()
    ];
    return msg;
} else {
    node.warn('⚠️ Config 가져오기 실패: status=' + msg.statusCode + ' payload=' + JSON.stringify(msg.payload).substring(0, 200));
    node.status({ fill: 'red', shape: 'dot', text: 'config 실패' });
    return null;
}

const status = global.get('systemStatus') || {};
msg.payload = {
    success: true,
    data: {
        operationMode: global.get('operationMode') || 'online',
        serverOnline: global.get('serverOnline') || false,
        manualOverride: global.get('manualOverride') || false,
        lastCheck: status.lastCheck || null
    }
};
msg.headers = { 'Access-Control-Allow-Origin': '*' };
return msg;

const { manual } = msg.payload;

if (typeof manual !== 'boolean') {
    msg.payload = { success: false, error: 'manual (boolean) 필수' };
    msg.statusCode = 400;
    return msg;
}

global.set('manualOverride', manual);

// 즉시 모드 재계산
const serverOnline = global.get('serverOnline') || false;
const operationMode = manual ? 'offline' : (serverOnline ? 'online' : 'offline');
global.set('operationMode', operationMode);

const modeLabel = operationMode === 'online' ? '온라인' : '오프라인';
const manualLabel = manual ? '수동' : '자동';

node.warn(`🔄 모드 전환: ${manualLabel} → ${modeLabel}`);
node.status({
    fill: manual ? 'yellow' : 'green',
    shape: 'dot',
    text: `${manualLabel} → ${modeLabel}`
});

msg.payload = {
    success: true,
    data: {
        operationMode,
        serverOnline,
        manualOverride: manual
    }
};
msg.headers = { 'Access-Control-Allow-Origin': '*' };
return msg;

msg.headers = {
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
    'Access-Control-Allow-Headers': 'Content-Type, x-api-key'
};
msg.payload = '';
msg.statusCode = 204;
return msg;

var farmId = msg.req.params.farmId;
msg.topic = 'SELECT * FROM house_configs WHERE farm_id = $1 ORDER BY created_at ASC';
msg.payload = [farmId];
msg._farmId = farmId;
