} else {
    node.status({ fill: 'green', shape: 'dot', text: '큐 완료, 다음 배치 확인' });
    setTimeout(function () { node.send([null, { payload: 'next_batch' }]); }, 500);
    return null;
}

const mode = global.get('operationMode') || 'online';

if (mode !== 'online') {
    node.status({ fill: 'yellow', shape: 'ring', text: '오프라인 - 규칙 동기화 대기' });
    return null;
}

msg.topic = 'SELECT * FROM automation_rules WHERE synced = 0';
return msg;

const rows = msg.payload || [];

if (rows.length === 0) {
    node.status({ fill: 'green', shape: 'dot', text: '규칙 동기화 완료 (0건)' });
    return null;
}

const SERVER_URL = env.get('SERVER_URL') || 'https://api.smartgreen.kr';
const API_KEY = env.get('SENSOR_API_KEY') || '';
const farmId = env.get('FARM_ID') || 'farm_0001';

// SQLite 행 → PC API 호환 형태로 변환
var rules = rows.map(function(row) {
    var conditions, actions;
    try { conditions = JSON.parse(row.conditions); } catch(e) { conditions = []; }
    try { actions = JSON.parse(row.actions); } catch(e) { actions = []; }
    return {
        id: row.id,
        farmId: row.farm_id,
        houseId: row.house_id,
        name: row.name,
        description: row.description || '',
        enabled: row.enabled === 1,
        conditionLogic: row.condition_logic || 'AND',
        conditions: conditions,
        actions: actions,
        cooldownSeconds: row.cooldown_seconds || 300,
        priority: row.priority || 10,
        lastTriggeredAt: row.last_triggered_at || null,
        triggerCount: row.trigger_count || 0,
        createdAt: row.created_at,
        updatedAt: row.updated_at
    };
});

msg.url = SERVER_URL + '/api/automation/' + farmId + '/sync';
msg.method = 'POST';
msg.headers = { 'Content-Type': 'application/json', 'x-api-key': API_KEY };
msg.payload = { rules: rules };
msg._syncRuleIds = rows.map(function(r) { return r.id; });
msg._syncRuleCount = rows.length;

node.warn('📤 규칙 동기화 전송: ' + rows.length + '건');
node.status({ fill: 'blue', shape: 'dot', text: '규칙 전송 중: ' + rows.length + '건' });

return msg;

if (msg.statusCode === 200 || msg.statusCode === 201) {
    var ids = msg._syncRuleIds || [];
    if (ids.length === 0) return null;

    // 문자열 ID → placeholder 동적 생성
    var placeholders = ids.map(function(_, i) { return '$' + (i + 1); }).join(',');
    msg.topic = 'UPDATE automation_rules SET synced = 1 WHERE id IN (' + placeholders + ')';
    msg.payload = ids;

    node.warn('✅ 규칙 동기화 성공: ' + msg._syncRuleCount + '건 synced=1');
    node.status({ fill: 'green', shape: 'dot', text: '규칙 동기화 완료: ' + msg._syncRuleCount + '건' });
    return msg;
} else {
    node.warn('⚠️ 규칙 동기화 실패 (' + msg.statusCode + '): 다음 주기에 재시도');
    node.status({ fill: 'red', shape: 'ring', text: '규칙 동기화 실패: ' + msg.statusCode });
    return null;
}

const row = msg.payload[0] || {};
var unsynced = row.unsynced || 0;

// 프로그래스바용: 전체 미동기화 수를 global에 저장
global.set('totalUnsynced', unsynced);

msg.payload = {
    success: true,
    data: {
        total: row.total || 0,
        synced: row.synced || 0,
        unsynced: unsynced,
        oldestUnsynced: row.oldest_unsynced || null,
        operationMode: global.get('operationMode') || 'unknown',
        syncPaused: flow.get('syncPaused') || false,
        syncRunning: flow.get('syncRunning') || false,
        syncInitialCount: flow.get('syncInitialCount') || 0,
        syncedSoFar: flow.get('syncedSoFar') || 0,
        lastSyncResult: global.get('lastSyncResult') || null
    }
};
msg.headers = { 'Access-Control-Allow-Origin': '*' };
return msg;

flow.set('syncPaused', false);
flow.set('syncRunning', true);
flow.set('syncedSoFar', 0);

// totalUnsynced에서 초기값 설정 (상태 API 폴링 시 저장됨)
var totalUnsynced = global.get('totalUnsynced') || 0;
flow.set('syncInitialCount', totalUnsynced);

node.warn('▶️ 동기화 수동 시작 (미동기화: ' + totalUnsynced + '건)');

msg.payload = { success: true, message: '동기화를 시작합니다 (' + totalUnsynced + '건)' };
msg.headers = { 'Access-Control-Allow-Origin': '*' };

var triggerMsg = {};
node.send([null, triggerMsg]);

return [msg, null];

flow.set('syncPaused', true);
flow.set('syncRunning', false);
node.warn('⏸️ 동기화 일시 중지');
msg.payload = { success: true, message: '동기화를 중지했습니다' };
msg.headers = { 'Access-Control-Allow-Origin': '*' };
return msg;

node.warn('⏭️ 미동기화 데이터 동기화 안함 처리 완료');
msg.payload = { success: true, message: '미동기화 데이터를 동기화 안함으로 처리했습니다' };
msg.headers = { 'Access-Control-Allow-Origin': '*' };
return msg;

var farmId = env.get('FARM_ID') || 'farm_0001';
var houseId = env.get('HOUSE_ID') || 'house_0001';
var serverUrl = env.get('SERVER_URL') || 'https://api.smartgreen.kr';

msg.url = serverUrl + '/api/automation/' + farmId + '/active?houseId=' + houseId;
msg.method = 'GET';
msg.headers = { 'x-api-key': 'smartfarm-sensor-key' };
return msg;

var data = msg.payload;
if (!data || !data.success) {
    node.status({ fill: 'red', shape: 'dot', text: '서버 응답 실패' });
    return null;
}

// 견고성: backend 가 단일 진실 원천 — MQTT 발송 실패해도 5분마다 fetch 로 sync 보장
// (이전 정책: MQTT 권한 소스 → MQTT 끊기면 RPi 영구 미동기화 결함)
var currentAutoDevices = global.get('autoDevices') || [];
var serverAutoDevices = data.autoDevices || [];

var newAutoDevices = data.active ? serverAutoDevices : [];
var changed = JSON.stringify(currentAutoDevices) !== JSON.stringify(newAutoDevices);
if (changed) {
    global.set('autoDevices', newAutoDevices);
    node.warn('🔄 서버에서 autoDevices 동기화: ' + JSON.stringify(currentAutoDevices) + ' → ' + JSON.stringify(newAutoDevices));
}

node.status({
    fill: currentAutoDevices.length > 0 ? 'green' : 'yellow',
    shape: 'dot',
    text: currentAutoDevices.length > 0
        ? '자동화 적용중 (' + currentAutoDevices.length + '개 장치)'
        : '자동화 미적용'
});

node.warn('🔄 서버 동기화: active=' + data.active + ', 서버=' + JSON.stringify(serverAutoDevices) + ', 현재=' + JSON.stringify(currentAutoDevices));
return null;

// ================================================================
// 릴레이 전체 OFF — 자동매핑 버전 (2026-05-02)
// ================================================================
// "릴레이 초기화" 탭 → "릴레이 전체 OFF" 함수 노드 코드 전체 교체
//
// 변경: Waveshare/Eletechsup unit-id 하드코딩 (1, 2) → global.relayModules 동적
//   - 모듈 추가/삭제/unit-id 변경 시 별도 수정 불필요
//   - 어제 Waveshare unit-id 1→2 변경 후 OFF 명령이 unit 1 에 가던 버그 해결
// ================================================================

const relayModules = global.get('relayModules') || [];

if (!Array.isArray(relayModules) || relayModules.length === 0) {
    msg.payload = { success: false, detail: '등록된 릴레이 모듈 없음' };
    msg.statusCode = 400;
    node.send([null, msg]);
    node.warn('⚠️ 릴레이 전체 OFF: 등록된 모듈 없음');
    return null;
}

var results = [];
var commands = [];

for (const mod of relayModules) {
    const moduleType = (mod.moduleType || 'waveshare').toLowerCase();
    const channels = mod.channels || 8;

    if (moduleType === 'eletechsup') {
        // FC06 single write, 1-indexed register, value 512 = OFF (0x0200)
        for (let i = 1; i <= channels; i++) {
            commands.push({
                payload: { unitid: mod.unitId, fc: 6, address: i, value: 512, quantity: 1 },
                label: 'Eletechsup uid:' + mod.unitId + ' CH' + (i - 1),
            });
        }
    } else {
        // Waveshare FC15 multi-coil write, 0-indexed
        commands.push({
            payload: {
                unitid: mod.unitId,
                fc: 15,
                address: 0,
                quantity: channels,
                value: new Array(channels).fill(0),
            },
            label: (mod.name || 'Waveshare') + ' uid:' + mod.unitId + ' ' + channels + 'CH',
        });
    }
}

var sent = 0;
var total = commands.length;

function sendNext() {
    if (sent >= total) {
        msg.payload = {
            success: true,
            detail: total + '개 명령 전송',
            results: results,
        };
        msg.statusCode = 200;
        node.send([null, msg]);
        node.warn('🔄 릴레이 전체 OFF 완료: ' + total + '개 명령 (' + relayModules.length + ' 모듈)');
        return;
    }

    var cmd = commands[sent];
    var m = RED.util.cloneMessage(msg);
    m.payload = cmd.payload;
    results.push(cmd.label + ' → OFF');
    sent++;

    node.send([m, null]);

    if (sent < total) {
        setTimeout(sendNext, 200);
    } else {
        setTimeout(sendNext, 300);
    }
}

sendNext();
return null;

// ================================================================
// 릴레이 워치독 — houseConfig에서 모듈 자동 감지
// ================================================================
// 센서 폴링 완료 5초 후 실행 → RS-485 버스 충돌 없음
// 최소 60초 간격 보장 (센서 폴링이 더 잦아도 스킵)
// ================================================================

var lastCheck = context.get('lastCheck') || 0;
if (Date.now() - lastCheck < 55000) {
    return null;
}
context.set('lastCheck', Date.now());

var houseConfig = global.get('houseConfig');
var modules = [];
var seenUnits = {};

if (houseConfig && houseConfig.houses) {
    for (var i = 0; i < houseConfig.houses.length; i++) {
        var devices = houseConfig.houses[i].devices || [];
        for (var j = 0; j < devices.length; j++) {
            var mb = devices[j].modbus;
            if (!mb || !mb.unitId || seenUnits[mb.unitId]) continue;
            seenUnits[mb.unitId] = true;

            var mod = { unitId: mb.unitId, moduleType: mb.moduleType || 'waveshare' };

            if (mod.moduleType === 'waveshare') {
                mod.readFc = 1;  mod.readAddr = 0;
                mod.resetFc = 15; mod.resetAddr = 0; mod.resetQty = 8;
                mod.resetValue = [0,0,0,0,0,0,0,0];
            } else if (mod.moduleType === 'eletechsup') {
                mod.readFc = 3;  mod.readAddr = 1;
                mod.resetFc = 6; mod.resetAddr = 1; mod.resetQty = 1;
                mod.resetValue = 0;
            } else {
                mod.readFc = 1;  mod.readAddr = 0;
                mod.resetFc = 15; mod.resetAddr = 0; mod.resetQty = 8;
                mod.resetValue = [0,0,0,0,0,0,0,0];
            }
            modules.push(mod);
        }
    }
}

if (modules.length === 0) {
    node.status({fill:'grey', shape:'dot', text:'릴레이 모듈 없음'});
    return null;
}

global.set('_watchdogModules', modules);

// ★ 깨끗한 새 메시지 생성 (cloneMessage 제거)
var first = modules[0];
var msg1 = {
    payload: { unitid: first.unitId, fc: first.readFc, address: first.readAddr, quantity: 1 },
    _watchdog: { module: first.moduleType + '_' + first.unitId, unitId: first.unitId }
};

for (var k = 1; k < modules.length; k++) {
    (function(mod, idx) {
        setTimeout(function() {
            node.send({
                payload: { unitid: mod.unitId, fc: mod.readFc, address: mod.readAddr, quantity: 1 },
                _watchdog: { module: mod.moduleType + '_' + mod.unitId, unitId: mod.unitId }
            });
        }, idx * 3000);
    })(modules[k], k);
}

node.status({fill:'blue', shape:'dot', text: modules.length + '개 모듈 ' + new Date().toLocaleTimeString()});
return msg1;

// ================================================================
// 워치독 판정 — 실패 카운트 + 알림 + 복구
// ================================================================
var info = msg._watchdog;
if (!info) return null;

// stale 카운터 자가청소 — 모듈 교체(unitId 변경/제거) 시 옛 카운터 자동 정리
(function () {
    var currentModules = global.get('_watchdogModules') || [];
    var validKeys = {};
    currentModules.forEach(function (m) { validKeys[m.moduleType + '_' + m.unitId] = true; });
    var f = context.get('failures') || {};
    var a = context.get('alerts') || {};
    var n = context.get('lastNotified') || {};
    var cleaned = false;
    Object.keys(f).forEach(function (k) {
        if (!validKeys[k]) { delete f[k]; cleaned = true; }
    });
    Object.keys(a).forEach(function (k) { if (!validKeys[k]) delete a[k]; });
    Object.keys(n).forEach(function (k) { if (!validKeys[k]) delete n[k]; });
    if (cleaned) {
        context.set('failures', f);
        context.set('alerts', a);
        context.set('lastNotified', n);
        global.set('watchdogAlert', Object.keys(a).length > 0 ? a : null);
        node.warn('🧹 stale 카운터 정리됨');
    }
})();

var moduleName = info.module;
var ok = msg._watchdogOk;
var THRESHOLD = 3;

var modules = global.get('_watchdogModules') || [];
var moduleConfig = null;
for (var i = 0; i < modules.length; i++) {
    if (modules[i].moduleType + '_' + modules[i].unitId === moduleName) {
        moduleConfig = modules[i];
        break;
    }
}

var failures = context.get('failures') || {};
var alerts = context.get('alerts') || {};
var history = context.get('history') || [];

history.push({ module: moduleName, ok: ok, time: new Date().toISOString() });
if (history.length > 30) history = history.slice(-30);
context.set('history', history);

function updateGlobalStatus() {
    var status = {};
    modules.forEach(function(m) {
        var key = m.moduleType + '_' + m.unitId;
        status[key] = { ok: (failures[key] || 0) === 0, failCount: failures[key] || 0 };
    });
    status.lastCheck = new Date().toISOString();
    global.set('watchdogStatus', status);
}

function statusText() {
    return modules.map(function(m) {
        var key = m.moduleType + '_' + m.unitId;
        return m.moduleType.charAt(0).toUpperCase() + m.unitId + ':' + (failures[key] || 0);
    }).join(' ') + ' ' + new Date().toLocaleTimeString();
}

if (ok) {
    if ((failures[moduleName] || 0) > 0) {
        node.warn('✅ ' + moduleName + ' 복구됨 (이전 ' + failures[moduleName] + '회 실패)');
    }
    failures[moduleName] = 0;
    if (alerts[moduleName]) {
        delete alerts[moduleName];
        global.set('watchdogAlert', Object.keys(alerts).length > 0 ? alerts : null);
    }
    context.set('failures', failures);
    context.set('alerts', alerts);
    updateGlobalStatus();
    node.status({ fill: 'green', shape: 'dot', text: statusText() });
    return [{ payload: '✅ ' + moduleName + ' 정상' }, null, null];
}

failures[moduleName] = (failures[moduleName] || 0) + 1;
node.warn('❌ ' + moduleName + ' 응답 없음 (' + failures[moduleName] + '회)');

context.set('failures', failures);
updateGlobalStatus();

if (failures[moduleName] < THRESHOLD) {
    node.status({ fill: 'yellow', shape: 'dot', text: statusText() });
    return [{ payload: '⚠️ ' + moduleName + ' 실패 ' + failures[moduleName] + '회' }, null, null];
}

var alertInfo = {
    module: moduleName,
    unitId: info.unitId,
    failCount: failures[moduleName],
    since: alerts[moduleName] ? alerts[moduleName].since : new Date().toISOString(),
    lastCheck: new Date().toISOString()
};
alerts[moduleName] = alertInfo;
context.set('alerts', alerts);
global.set('watchdogAlert', alerts);

node.warn('🚨 ' + moduleName + ' 장애! ' + failures[moduleName] + '회 — 복구 시도');

var recoveryMsg = null;
if (moduleConfig) {
    recoveryMsg = RED.util.cloneMessage(msg);
    recoveryMsg.payload = {
        value: moduleConfig.resetValue,
        unitid: moduleConfig.unitId,
        fc: moduleConfig.resetFc,
        address: moduleConfig.resetAddr,
        quantity: moduleConfig.resetQty
    };
}

node.status({ fill: 'red', shape: 'ring', text: '🚨 ' + statusText() });

return [
    { payload: '🚨 ' + moduleName + ' 장애 (' + failures[moduleName] + '회)' },
    recoveryMsg,
    { payload: alertInfo }
];

var alert = global.get('watchdogAlert') || null;
var status = global.get('watchdogStatus') || { lastCheck: null };

msg.payload = {
    status: status,
    alert: alert,
    timestamp: new Date().toISOString()
};
msg.headers = { 'Content-Type': 'application/json' };
return msg;

// ================================================================
// MQTT 릴레이 조회 처리 — 등록된 모듈 자동 인식 (2026-05-01)
// ================================================================
// "Modbus 릴레이 읽기 + 응답" 함수 노드의 코드 전체 교체
//
// ⚠️ 기존 코드는 unitid:1, fc:1 (Waveshare) 하드코딩 → Eletechsup 등록 시 동작 안 함
// ✅ 새 코드는 "모듈 동기화" 탭이 PC 백엔드에서 받아 global 에 캐싱한 relayModules 사용
//
// 동작:
//   1. global.relayModules (modsync_handler 가 저장) 조회
//   2. 첫 모듈을 즉시 호출 (waveshare → FC1 coils, eletechsup → FC3 register)
//   3. 모듈이 여러 개면 1초 간격으로 순차 호출 (RS-485 충돌 방지)
//
// 출력:
//   1: Modbus 호출 (modbus-flex-getter)
//   2: (사용 안 함)
// ================================================================

let relayModules = global.get('relayModules');
if (!Array.isArray(relayModules)) relayModules = [];

// fallback: houseConfig.devices 에서 unit 추출 (모듈 동기화 미가동 시)
if (relayModules.length === 0) {
    const houseConfig = global.get('houseConfig');
    if (houseConfig && Array.isArray(houseConfig.houses)) {
        const seen = {};
        for (const h of houseConfig.houses) {
            for (const d of (h.devices || [])) {
                const mb = d.modbus;
                if (!mb || !mb.unitId || seen[mb.unitId]) continue;
                seen[mb.unitId] = true;
                relayModules.push({
                    unitId: mb.unitId,
                    moduleType: mb.moduleType || 'waveshare',
                    channels: 8,
                });
            }
        }
    }
}

if (relayModules.length === 0) {
    node.status({ fill: 'grey', shape: 'dot', text: '등록 모듈 없음' });
    node.warn('relay/query: 등록된 릴레이 모듈이 없습니다');
    return null;
}

// ───────── 모듈별 Modbus 요청 생성 ─────────
function buildModbusMsg(mod) {
    const moduleType = (mod.moduleType || 'waveshare').toLowerCase();
    if (moduleType === 'eletechsup') {
        // FC3 (Read Holding Registers), 1-indexed (channel 1..N)
        return {
            payload: {
                unitid: mod.unitId,
                fc: 3,
                address: 1,
                quantity: mod.channels || 8,
            },
            topic: 'relay_query',
            _module: { unitId: mod.unitId, moduleType: 'eletechsup', channels: mod.channels || 8 },
        };
    }
    // 기본: Waveshare (FC1 Read Coils, 0-indexed)
    return {
        payload: {
            unitid: mod.unitId,
            fc: 1,
            address: 0,
            quantity: mod.channels || 8,
        },
        topic: 'relay_query',
        _module: { unitId: mod.unitId, moduleType: 'waveshare', channels: mod.channels || 8 },
    };
}

const first = buildModbusMsg(relayModules[0]);

// 나머지 모듈은 1초 간격으로 순차 발송 (RS-485 충돌 회피)
for (let i = 1; i < relayModules.length; i++) {
    (function (mod, idx) {
        setTimeout(function () {
            node.send([buildModbusMsg(mod), null]);
        }, idx * 1000);
    })(relayModules[i], i);
}

node.status({ fill: 'blue', shape: 'dot', text: relayModules.length + '개 모듈 query ' + new Date().toLocaleTimeString() });
return [first, null];

// Modbus 읽기 결과 → MQTT 응답 포맷
const farmId = global.get('houseConfig')?.farmId 
            || global.get('farmId') 
            || env.get('FARM_ID') 
            || 'farm_0001';

const coils = {};

if (msg.payload && Array.isArray(msg.payload)) {
    msg.payload.forEach((val, idx) => {
        coils[idx] = !!val;
    });
}

msg.topic = `smartfarm/${farmId}/relay/response`;
msg.payload = {
    farmId: farmId,
    unitId: 1,
    moduleType: 'waveshare',
    coils: coils,
    timestamp: new Date().toISOString()
};

node.warn('📡 릴레이 상태 MQTT 발행: ' + JSON.stringify(coils));
return msg;

// 제어 실행 완료 후 릴레이 상태를 MQTT로 발행
const farmId = global.get('houseConfig')?.farmId 
            || global.get('farmId') 
            || env.get('FARM_ID') 
            || 'farm_0001';

// 1초 후 Modbus 읽기 (릴레이 안정화 대기)
setTimeout(() => {
    node.send({
        payload: {
            unitid: 1,
            fc: 1,
            address: 0,
            quantity: 8
        },
        topic: 'relay_status_after_control'
    });
}, 1000);

return null;

// MQTT로 수신한 autoDevices를 global context에 저장
const data = msg.payload;
if (data && data.action === 'set_autoDevices') {
    const autoDevices = data.autoDevices || [];
    global.set('autoDevices', autoDevices);
    node.warn('📡 autoDevices 업데이트 (MQTT): ' + JSON.stringify(autoDevices));

    // 자동화 규칙 재로드 트리거
    return { payload: 'reload', topic: 'autoDevices_updated' };
}
return null;

const data = msg.payload;
const action = data.action;

node.warn('🔧 시스템 명령 수신: ' + action + ' (by ' + (data.operator || 'unknown') + ')');

if (action === 'restart-nodered') {
    msg.payload = 'pm2 restart node-red';
    return msg;
} else if (action === 'restart-rpi-express' || action === 'restart-express') {
    msg.payload = 'pm2 restart smartfarm-rpi';
    return msg;
} else {
    node.warn('⚠️ 알 수 없는 시스템 명령: ' + action);
    return null;
}

// ================================================================
// modsync_trigger — 백엔드 system-settings GET 요청 준비 (2026-05-01 final)
// ================================================================
// "모듈 동기화" 탭 → "백엔드 API 호출 준비" 함수 노드 코드 전체 교체
//
// 캐시 무력화: _t 쿼리 파라미터 + no-cache 헤더 (Cloudflare/Node-RED HTTP 캐시 회피)
// ================================================================

const farmId = global.get('farmId') || env.get('FARM_ID') || 'farm_0001';
const pcServer = global.get('pcServerUrl') || 'https://api.smartgreen.kr';
const apiKey = global.get('sensorApiKey') || 'smartfarm-sensor-key';

const source = msg.topic === 'scheduled_sync' ? '검증' : '즉시';

msg.method = 'GET';
msg.url = pcServer + '/api/config/system-settings/' + farmId + '?_t=' + Date.now();
msg.headers = {
    'x-api-key': apiKey,
    'Cache-Control': 'no-cache',
    'Pragma': 'no-cache',
    'If-None-Match': '',
    'Accept-Encoding': 'identity',
    'Accept': 'application/json',
};
msg.payload = null;
msg._syncSource = source;

node.status({ fill: 'blue', shape: 'dot', text: source + ' 요청' });
return msg;

// ================================================================
// modsync_handler — 응답 파싱 → global.relayModules / sensorModules 캐싱 (2026-05-01 final)
// ================================================================
// "모듈 동기화" 탭 → "모듈 정보 → global context" 함수 노드 코드 전체 교체
//
// 동작:
//   1. http request 응답 (msg.payload) 파싱
//   2. settings.relayModules / sensorModules 추출
//   3. global 컨텍스트에 캐싱
//   4. 변경 감지 시 warn 출력
// ================================================================

// payload 가 string 으로 온 경우 파싱 시도 (방어적)
let payload = msg.payload;
if (typeof payload === 'string') {
    try { payload = JSON.parse(payload); }
    catch (e) {
        node.error('payload JSON 파싱 실패: ' + e.message);
        node.status({ fill: 'red', shape: 'dot', text: 'parse 실패' });
        return null;
    }
}

if (msg.statusCode !== 200) {
    node.error('❌ Sync 실패 status=' + msg.statusCode + ' source=' + msg._syncSource);
    node.status({ fill: 'red', shape: 'dot', text: 'API ' + msg.statusCode });
    return null;
}

const data = (payload && payload.data) || {};
const settings = data.settings || {};
const relayModules = Array.isArray(settings.relayModules) ? settings.relayModules : [];
const sensorModules = Array.isArray(settings.sensorModules) ? settings.sensorModules : [];

const prevRelay = global.get('relayModules') || [];
const prevSensor = global.get('sensorModules') || [];

global.set('relayModules', relayModules);
global.set('sensorModules', sensorModules);
global.set('modulesSyncedAt', new Date().toISOString());

const changed = (prevRelay.length !== relayModules.length) || (prevSensor.length !== sensorModules.length);
const source = msg._syncSource || '?';

node.status({
    fill: 'green',
    shape: 'dot',
    text: source + ' R:' + relayModules.length + ' S:' + sensorModules.length + (changed ? ' ★변경' : '')
});

if (changed) {
    node.warn('🔄 모듈 변경 감지 (' + source + '): relay=' + relayModules.length + ' sensor=' + sensorModules.length);
}

msg.payload = { relayModules, sensorModules, changed, source };
return msg;

// backend publishConfigUpdate 의 type 으로 분기
// modules_changed → 기존 modsync_trigger 가 처리 (system-settings)
// house_created/house_changed/house_deleted → 이 flow 가 houseConfig refresh

// payload 가 string 으로 올 수도 있음 (datatype=auto 또는 JSON parse 실패 시)
let data = msg.payload;
if (typeof data === 'string') {
    try { data = JSON.parse(data); } catch (e) {
        node.warn('hcs_filter: payload JSON 파싱 실패: ' + e.message);
        return null;
    }
}
if (!data || typeof data !== 'object') return null;

const type = data.type || '';

// houseConfig 영향 type 만 통과
if (!type.startsWith('house_')) {
    return null;  // modules_changed 등은 modsync_trigger 가 처리
}

const farmId = global.get('farmId') || env.get('FARM_ID') || 'farm_0001';
const pcServer = global.get('pcServerUrl') || 'https://api.smartgreen.kr';
const apiKey = global.get('sensorApiKey') || 'smartfarm-sensor-key';

msg.method = 'GET';
msg.url = pcServer + '/api/config/farm/' + farmId + '?_t=' + Date.now();
msg.headers = {
    'x-api-key': apiKey,
    'Cache-Control': 'no-cache',
    'Accept': 'application/json',
};
msg.payload = null;
msg._farmId = farmId;
msg._eventType = type;

node.warn('🏠 houseConfig refresh trigger: ' + type);
node.status({ fill: 'blue', shape: 'dot', text: type + ' ' + new Date().toLocaleTimeString() });
return msg;

// PC backend /config/farm/{farmId} 응답 → global.houseConfig 갱신

let payload = msg.payload;
if (typeof payload === 'string') {
    try { payload = JSON.parse(payload); } catch (e) {
        node.error('houseConfig 응답 파싱 실패: ' + e.message);
        return null;
    }
}

if (msg.statusCode !== 200) {
    node.error('❌ houseConfig 조회 실패 status=' + msg.statusCode);
    node.status({ fill: 'red', shape: 'dot', text: 'API ' + msg.statusCode });
    return null;
}

const houses = (payload && payload.success && Array.isArray(payload.data)) ? payload.data : [];
if (houses.length === 0) {
    node.warn('houseConfig 빈 응답 — refresh 안 함');
    return null;
}

const farmId = msg._farmId || 'farm_0001';
const eventType = msg._eventType || '?';

// 기존 houseConfig 와 비교
const prev = global.get('houseConfig') || {};
const prevHouses = prev.houses || [];

// houseConfig 구조 (워치독/sensor 폴링이 사용하는 형식)
const newHouseConfig = {
    farmId,
    houses: houses.map(h => ({
        id: h.houseId,
        houseId: h.houseId,
        name: h.houseName || h.name,
        enabled: h.enabled !== false,
        sensors: h.sensors || [],
        devices: h.devices || [],
        configVersion: h.configVersion || 0,
    })),
    configVersion: Math.max(0, ...houses.map(h => h.configVersion || 0)),
};

global.set('houseConfig', newHouseConfig);
global.set('houseConfigUpdatedAt', new Date().toISOString());

// 워치독 캐시 무효화 (modules 변경 시 워치독이 옛 sensor 폴링 안 하도록)
global.set('_watchdogModules', null);

const sensorTotal = houses.reduce((sum, h) => sum + (h.sensors?.length || 0), 0);
const deviceTotal = houses.reduce((sum, h) => sum + (h.devices?.length || 0), 0);

node.status({
    fill: 'green', shape: 'dot',
    text: eventType + ' H:' + houses.length + ' S:' + sensorTotal + ' D:' + deviceTotal
});
node.warn('🏠 houseConfig refresh (' + eventType + '): ' + houses.length + ' houses, ' + sensorTotal + ' sensors, ' + deviceTotal + ' devices');

return null;

// global.sensorModules 의 모든 모듈을 sequential read
// Waveshare relay/query 와 동일 패턴 — RS-485 충돌 회피 위해 1초 간격 발사

const farmId = global.get('FARM_ID') || env.get('FARM_ID') || 'farm_0001';
const sensorModules = global.get('sensorModules') || [];

if (!Array.isArray(sensorModules) || sensorModules.length === 0) {
    node.status({ fill: 'grey', shape: 'dot', text: '등록 모듈 없음' });
    node.warn('sensor/query: 등록된 센서 모듈이 없습니다');
    return null;
}

function buildMsg(mod) {
    return {
        payload: {
            unitid: mod.unitId,
            fc: mod.fc || 3,
            address: mod.address || 0,
            quantity: mod.quantity || 1,
        },
        topic: 'sensor_query',
        _module: {
            unitId: mod.unitId,
            fc: mod.fc || 3,
            address: mod.address || 0,
            quantity: mod.quantity || 1,
            divider: mod.divider || 1,
            signed: mod.signed || false,
            sensorType: mod.sensorType,
            farmId: farmId,
        },
    };
}

const first = buildMsg(sensorModules[0]);

// 나머지 모듈 1초 간격으로 순차 발송
for (let i = 1; i < sensorModules.length; i++) {
    (function (mod, idx) {
        setTimeout(function () {
            node.send(buildMsg(mod));
        }, idx * 1000);
    })(sensorModules[i], i);
}

node.status({ fill: 'blue', shape: 'dot', text: sensorModules.length + '개 모듈 query ' + new Date().toLocaleTimeString() });
return first;

// modbus-flex-getter 응답 → MQTT smartfarm/{farmId}/sensor/status
// payload.responseBuffer.data: 16-bit register 배열

const mod = msg._module || {};
const farmId = mod.farmId || global.get('FARM_ID') || env.get('FARM_ID') || 'farm_0001';

const raw = (msg.payload && Array.isArray(msg.payload)) ? msg.payload
           : (msg.payload && msg.payload.data) ? msg.payload.data
           : (msg.responseBuffer && msg.responseBuffer.data) ? msg.responseBuffer.data
           : [];

if (!Array.isArray(raw) || raw.length === 0) {
    node.warn('sensor/query: empty raw — unitId=' + mod.unitId);
    return null;
}

msg.topic = 'smartfarm/' + farmId + '/sensor/status';
msg.payload = {
    unitId: mod.unitId,
    fc: mod.fc,
    address: mod.address,
    quantity: mod.quantity,
    raw: raw,
    divider: mod.divider,
    signed: mod.signed,
    sensorType: mod.sensorType,
    timestamp: new Date().toISOString(),
};
msg.qos = 1;
msg.retain = false;

node.status({ fill: 'green', shape: 'dot', text: 'unit ' + mod.unitId + ': ' + raw.slice(0,2).join(',') });
return msg;

// RPi Express (smartfarm-rpi, port 3001 또는 1880 nginx) 의 /api/sync/status 호출
// MQTT 메시지의 farmId 를 응답에 포함하기 위해 보존
const topicParts = (msg.topic || '').split('/');
const farmId = topicParts[1] || global.get('FARM_ID') || env.get('FARM_ID') || 'farm_0001';

msg._farmId = farmId;
msg.method = 'GET';
msg.url = 'http://localhost:1880/api/sync/status';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = null;

node.status({ fill: 'blue', shape: 'dot', text: 'GET ' + farmId });
return msg;

// HTTP 응답 → MQTT smartfarm/{farmId}/sync/status
const farmId = msg._farmId || 'farm_0001';

let data = msg.payload;
if (typeof data === 'string') {
    try { data = JSON.parse(data); } catch (e) {
        node.warn('sync/status 응답 파싱 실패: ' + e.message);
        return null;
    }
}

// data.success 가 true 이면 data.data 가 실제 sync status
const statusData = (data && data.success && data.data) ? data.data : (data || {});

msg.topic = 'smartfarm/' + farmId + '/sync/status';
msg.payload = {
    ...statusData,
    timestamp: new Date().toISOString(),
};
msg.qos = 1;
msg.retain = false;

node.status({
    fill: 'green', shape: 'dot',
    text: 'unsynced=' + (statusData.unsynced || 0) + ' synced=' + (statusData.synced || 0)
});
return msg;

// MQTT payload.action (start/stop/skip) → /api/sync/{action} POST 호출
const data = msg.payload || {};
const action = data.action;

if (!['start', 'stop', 'skip'].includes(action)) {
    node.warn('잘못된 sync action: ' + action);
    return null;
}

const topicParts = (msg.topic || '').split('/');
const farmId = topicParts[1] || 'farm_0001';

msg.method = 'POST';
msg.url = 'http://localhost:1880/api/sync/' + action;
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = { operator: data.operator || 'unknown', farmId };
msg._farmId = farmId;
msg._action = action;

node.status({ fill: 'blue', shape: 'dot', text: action + ' ' + farmId });
return msg;

const farmId = msg._farmId || 'farm_0001';
const action = msg._action || '?';
const ok = msg.statusCode === 200 && msg.payload && msg.payload.success !== false;

node.status({
    fill: ok ? 'green' : 'red',
    shape: 'dot',
    text: action + ' ' + (ok ? 'OK' : 'fail') + ' ' + farmId
});

if (ok) {
    node.warn('sync/' + action + ' 완료: ' + farmId);
} else {
    node.warn('sync/' + action + ' 실패: ' + farmId + ' status=' + msg.statusCode);
}

// 명령 후 status 자동 갱신을 위해 sync/query 트리거 (1초 대기)
setTimeout(function() {
    node.send({
        method: 'GET',
        url: 'http://localhost:1880/api/sync/status',
        headers: { 'Content-Type': 'application/json' },
        payload: null,
        _farmId: farmId,
    });
}, 1000);

return null;

// MQTT 토픽에서 farmId 추출하여 보존 (응답에 포함)
const topicParts = (msg.topic || '').split('/');
const farmId = topicParts[1] || global.get('FARM_ID') || env.get('FARM_ID') || 'farm_0001';

msg._farmId = farmId;
msg.payload = '';  // exec 노드 입력은 빈 문자열 (command 자체에 인자 없음)

node.status({ fill: 'blue', shape: 'dot', text: 'pm2 jlist ' + farmId });
return msg;

// pm2 jlist 의 stdout (JSON 배열) 파싱 후 process 별 status 추출
const farmId = msg._farmId || 'farm_0001';

let processes = [];
try {
    processes = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload;
    if (!Array.isArray(processes)) processes = [];
} catch (e) {
    node.warn('pm2 jlist 파싱 실패: ' + e.message);
    return null;
}

function extract(name) {
    const p = processes.find(x => x.name === name);
    if (!p) return null;
    const env = p.pm2_env || {};
    return {
        status: env.status || 'unknown',
        uptime: env.pm_uptime || null,  // ms epoch (start time)
        restarts: env.restart_time || 0,
        unstableRestarts: env.unstable_restarts || 0,
        pid: p.pid || null,
        memory: p.monit?.memory || 0,
        cpu: p.monit?.cpu || 0,
    };
}

const status = {
    nodeRed: extract('node-red'),
    rpiExpress: extract('smartfarm-rpi'),
    smartfarmSystem: extract('smartfarm-system'),
};

msg.topic = 'smartfarm/' + farmId + '/system/status';
msg.payload = {
    ...status,
    farmId,
    timestamp: new Date().toISOString(),
};
msg.qos = 1;
msg.retain = false;

const nrUp = status.nodeRed?.status === 'online' ? '✓' : '✗';
const expUp = status.rpiExpress?.status === 'online' ? '✓' : '✗';
node.status({
    fill: 'green', shape: 'dot',
    text: 'NR:' + nrUp + ' EXP:' + expUp + ' (' + new Date().toLocaleTimeString() + ')'
});
return msg;

// MQTT로 수신한 device-positions를 global context에 즉시 동기화
const data = msg.payload;
if (data && data.action === 'set_device_position' && data.deviceId) {
    const positions = global.get('devicePositions') || {};
    const before = positions[data.deviceId];
    positions[data.deviceId] = data.position;
    global.set('devicePositions', positions);
    node.warn('📍 device-position 갱신 (MQTT): ' + data.deviceId + ' ' + before + ' → ' + data.position + ' (cmd=' + data.command + ')');
}
return null;
